17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.ArrayList;
23	import java.util.Collection;
24	import java.util.List;
25	import java.util.Locale;
26	import java.util.regex.Pattern;
27	
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.util.StringUtils;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    /**
75	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
76	     * and a domain containing at least one dot, with no whitespace in any segment.
77	     */
78	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        validateRequiredFields(ownerFieldsDto);
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
122	            joinHousehold(owner);
123	        } else {
124	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
125	        }
126	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
127	        requireUniqueTelephone(telephone);
128	        owner.setTelephone(telephone);
129	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
130	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
131	        this.clinicService.saveOwner(owner);
132	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
133	        headers.setLocation(UriComponentsBuilder.newInstance()
134	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
135	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
136	    }
137	
138	    /**
139	     * Generates the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}.
140	     * {@code LAST3} is the upper-cased first three letters of the last name and {@code NNNN} is a
141	     * global, 4-digit zero-padded sequence equal to one more than the current number of owners
142	     * (e.g. {@code 'SMI-0007'}).
143	     *
144	     * @param lastName the owner's last name
145	     * @return the generated customer code
146	     */
147	    private String generateCustomerCode(String lastName) {
148	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
149	        int sequence = this.clinicService.findAllOwners().size() + 1;
150	        return String.format("%s-%04d", last3, sequence);
151	    }
152	
153	    /**
154	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
155	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
156	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
157	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
158	     *
159	     * @param ownerFieldsDto the submitted owner fields
160	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
161	     */
162	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
163	        List<String> invalidFields = new ArrayList<>();
164	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
165	            invalidFields.add("firstName");
166	        }
167	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
168	            invalidFields.add("lastName");
169	        }
170	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
171	            invalidFields.add("address");
172	        }
173	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
174	            invalidFields.add("city");
175	        }
176	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
177	            invalidFields.add("telephone");
178	        }
179	        if (!invalidFields.isEmpty()) {
180	            throw new InvalidOwnerFieldsException(invalidFields);
181	        }
182	    }
183	
184	    /**
185	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
186	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
187	     * what gets stored and returned.
188	     *
189	     * @param telephone the raw telephone value from the request
190	     * @return the normalized E.164 telephone number
191	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
192	     */
193	    private String normalizeTelephone(String telephone) {
194	        String e164 = toE164(telephone);
195	        if (e164 == null) {
196	            throw new InvalidOwnerFieldsException(List.of("telephone"));
197	        }
198	        return e164;
199	    }
200	
201	    /**
202	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
203	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
204	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
205	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
206	     * it contains 8 to 15 digits after the {@code '+'}.
207	     *
208	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
209	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
210	     *
211	     * @param telephone the raw telephone value, possibly {@code null}
212	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
213	     */
214	    private String toE164(String telephone) {
215	        if (telephone == null) {
216	            return null;
217	        }
218	        String cleaned = telephone.replaceAll("[ \\-()]", "");
219	        String digits;
220	        if (cleaned.startsWith("+")) {
221	            digits = cleaned.substring(1);
222	        } else {
223	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
224	            digits = "61" + national;
225	        }
226	        if (!digits.matches("[0-9]{8,15}")) {
227	            return null;
228	        }
229	        return "+" + digits;
230	    }
231	
232	    /**
233	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
234	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
235	     * and returned lower-cased.
236	     *
237	     * @param email the raw email value from the request, possibly {@code null}
238	     * @return the lower-cased email, or {@code null} when none was supplied
239	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
240	     */
241	    private String normalizeEmail(String email) {
242	        if (!StringUtils.hasText(email)) {
243	            return null;
244	        }
245	        String trimmed = email.trim();
246	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
247	            throw new InvalidOwnerFieldsException(List.of("email"));
248	        }
249	        return trimmed.toLowerCase(Locale.ROOT);
250	    }
251	
252	    /**
253	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
254	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
255	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
256	     *
257	     * @param telephone the normalized (E.164) telephone of the owner being created
258	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
259	     */
260	    private void requireUniqueTelephone(String telephone) {
261	        boolean inUse = this.clinicService.findAllOwners().stream()
262	            .map(Owner::getTelephone)
263	            .filter(existing -> existing != null)
264	            .map(existing -> {
265	                String e164 = toE164(existing);
266	                return e164 != null ? e164 : existing;
267	            })
268	            .anyMatch(telephone::equals);
269	        if (inUse) {
270	            throw new DuplicateTelephoneException(telephone);
271	        }
272	    }
273	
274	    /**
275	     * Rejects an owner whose last name and address match those of an existing owner, where both are
276	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
277	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
278	     *
279	     * @param lastName the last name of the owner being created
280	     * @param address the address of the owner being created
281	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
282	     */
283	    private void requireUniqueHousehold(String lastName, String address) {
284	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
285	            throw new DuplicateHouseholdException(lastName, address);
286	        }
287	    }
288	
289	    /**
290	     * Returns the existing owners that belong to the same household as the given last name and
291	     * address, i.e. those whose last name and address match case-insensitively and with runs of
292	     * whitespace collapsed to a single space.
293	     *
294	     * @param lastName the last name to match
295	     * @param address the address to match
296	     * @return the matching owners (possibly empty, never {@code null})
297	     */
298	    private List<Owner> findHouseholdMembers(String lastName, String address) {
299	        String normalizedLastName = normalizeForHousehold(lastName);
300	        String normalizedAddress = normalizeForHousehold(address);
301	        return this.clinicService.findAllOwners().stream()
302	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
303	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
304	            .toList();
305	    }
306	
307	    /**
308	     * Joins the owner being created to the shared household of any existing owner(s) that have the
309	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
310	     * member of the household - the existing owners and the new one - is assigned the same stable
311	     * {@code householdId}, so the shared identifier can be read back from any of them.
312	     *
313	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
314	     * the owner is left without a {@code householdId}.
315	     *
316	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
317	     */
318	    private void joinHousehold(Owner owner) {
319	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
320	        if (members.isEmpty()) {
321	            return;
322	        }
323	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
324	        owner.setHouseholdId(householdId);
325	        for (Owner member : members) {
326	            if (!householdId.equals(member.getHouseholdId())) {
327	                member.setHouseholdId(householdId);
328	                this.clinicService.saveOwner(member);
329	            }
330	        }
331	    }
332	
333	    /**
334	     * Computes the stable, shared household identifier for a last name and address. The value is
335	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
336	     * name and address, so every owner in the same household computes the same identifier.
337	     *
338	     * @param lastName the last name of the household
339	     * @param address the address of the household
340	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
341	     */
342	    private String computeHouseholdId(String lastName, String address) {
343	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
344	        try {
345	            byte[] digest = MessageDigest.getInstance("SHA-256")
346	                .digest(key.getBytes(StandardCharsets.UTF_8));
347	            StringBuilder hex = new StringBuilder();
348	            for (int i = 0; i < 6; i++) {
349	                hex.append(String.format("%02X", digest[i]));
350	            }
351	            return "HH-" + hex;
352	        } catch (NoSuchAlgorithmException e) {
353	            throw new IllegalStateException("SHA-256 algorithm not available", e);
354	        }
355	    }
356	
357	    /**
358	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
359	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
360	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
361	     *
362	     * @param value the raw value, possibly {@code null}
363	     * @return the normalized value
364	     */
365	    private String normalizeForHousehold(String value) {
366	        if (value == null) {
367	            return "";
368	        }
369	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
370	    }
371	
372	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
373	    @Override
374	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
375	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
376	        if (currentOwner == null) {
377	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
378	        }
379	        currentOwner.setAddress(ownerFieldsDto.getAddress());
380	        currentOwner.setCity(ownerFieldsDto.getCity());
381	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
