            invalidFields.add("firstName");
        }
        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
            invalidFields.add("lastName");
        }
        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
